var i=[{title:`Zwei häufige Anwendungen`,text:`Die Session-RPE bewertet die Gesamtschwierigkeit eines ganzen Trainings, oft auf einer Skala im Stil von Kategorie-Verhältnis-Skalen von 0–10, die von Ruhe bis maximaler Anstrengung reicht. Die Satz-RPE bewertet einen Krafttrainingssatz. Beide messen Verschiedenes: Ein Satz kann extrem hart sein innerhalb einer Einheit, die sich insgesamt moderat anfühlte.`},{title:`Satz-RPE und Wiederholungen in Reserve`,text:`Ein Krafttrainingssystem verknüpft jede Bewertung mit der Zahl der Wiederholungen, die du noch übrig glaubst. RPE 10 bedeutet, dass du keine weitere volle Wiederholung mit der beabsichtigten Technik geschafft hättest, RPE 9 bedeutet, dass eine übrig war, und RPE 8 bedeutet, dass etwa zwei übrig waren. Das sind Schätzungen, keine genauen physiologischen Messungen, und mit Trainingserfahrung wirst du darin besser.`},{title:`Beispiele`,text:`Ein zügiger 25-minütiger Spaziergang kann sich für eine Person wie 4/10 anfühlen und für einen untrainierten Anfänger wie 7/10. Ein Satz mit acht Kniebeugen, bei dem noch etwa zwei Wiederholungen möglich wären, wäre auf der Heben-Skala mit Wiederholungen in Reserve ungefähr RPE 8. Sage immer, welche Skala du nutzt, sonst werden die Zahlen verwirrend.`},{title:`Häufige Fehler`,text:`Bewertungen verlieren ihren Wert, wenn du die Anstrengung nur danach beurteilst, wie viel du schwitzt, Muskelkater mit der Schwierigkeit der Einheit verwechselst oder immer 10 wählst, weil ein Training „hart sein sollte“. Schlaf, Stress, Hitze und ungewohnte Bewegungen verändern alle, wie anstrengend Training sich anfühlt, lies jede Bewertung also in ihrem Zusammenhang.`},{title:`Bewertungen in Entscheidungen umsetzen`,text:`Wenn sich mehrere Einheiten deutlich härter anfühlen als geplant, sieh dir Schlaf, Last, Satzzahl, Pausen und Erholung an. Wenn sich Einheiten immer sehr leicht anfühlen und deine Technik solide ist, versuche beim nächsten Mal eine kleine Steigerung. Eine ungewöhnliche Bewertung reicht nicht aus, um Übertraining zu diagnostizieren oder große Änderungen vorzunehmen.`},{title:`TrainUp nutzen`,text:`Nach jedem Training bewertest du die ganze Einheit von 1 bis 10. Behandle diese Zahl als Anstrengung der Einheit und rechne sie nicht in Satz-RPE oder Wiederholungen in Reserve um. Sieh dir deine Bewertungen neben dem an, wie viel du von jedem Training geschafft hast, über mehrere Trainings hinweg.`}];var t=[{label:`Zourdos et al.: Forschung zur RIR-basierten RPE`,url:`https://pubmed.ncbi.nlm.nih.gov/26049792/`},{label:`Helms et al.: Praktische Hinweise zur RPE`,url:`https://pubmed.ncbi.nlm.nih.gov/27531969/`},{label:`CDC: Hinweise zur Anstrengung`,url:`https://www.cdc.gov/physical-activity-basics/measuring/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};